document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelector("[data-nav-toggle]"),t=document.querySelector("[data-menu]");e&&t&&e.addEventListener("click",()=>{const c=t.classList.toggle("open");e.setAttribute("aria-expanded",String(c))}),document.querySelectorAll("[data-slider]").forEach(e=>{const t=[...e.querySelectorAll(".slide")],c=[...e.querySelectorAll(".dots button")];let l=0;const o=e=>{l=(e+t.length)%t.length,t.forEach((e,t)=>e.classList.toggle("active",t===l)),c.forEach((e,t)=>e.classList.toggle("active",t===l))};c.forEach((e,t)=>e.addEventListener("click",()=>o(t))),o(0),setInterval(()=>o(l+1),3800)})});